async function fetchAllRows(makeQuery,maxRows=5000){
 const pageSize=500,rows=[];
 for(let from=0;from<maxRows;from+=pageSize){
  const{data,error}=await makeQuery().range(from,Math.min(from+pageSize-1,maxRows-1));
  if(error)throw error;
  rows.push(...(data||[]));
  if(!data||data.length<pageSize)return rows;
 }
 throw new Error('O histórico ultrapassou o limite de segurança de '+maxRows+' registros por tabela. Aplique filtros ou exporte o histórico.');
}
function dateISO(d){return d.toISOString().slice(0,10)}
function latestSunday(){const d=new Date();d.setHours(12,0,0,0);d.setDate(d.getDate()-d.getDay());return dateISO(d)}
function monthLabel(s){return new Date(s+'T12:00:00').toLocaleDateString('pt-BR',{month:'short',year:'2-digit'})}
function getTrend(points){if(points.length<2)return{kind:'none',delta:0};const a=Number(points[points.length-2].value),b=Number(points[points.length-1].value);return{kind:b>a?'up':b<a?'down':'same',delta:b-a}}
function makeAdvice(metric,trend,hasData){
if(!hasData)return'Ainda não há lançamentos suficientes. Registre os dados com regularidade antes de definir uma ação.';
const down=trend.kind==='down';
if(metric===ATTENDANCE)return down?'A frequência caiu no último período. Sugestão: o bispado e o conselho da Ala podem identificar, por meio da ministração e de conversas respeitosas, pessoas e famílias que precisam de apoio ou acolhimento. Planejem convites pessoais e removam barreiras práticas quando possível. Como exemplo histórico, a Ala Ubon, na Tailândia, relatou uma iniciativa de convite coordenado para um domingo específico, com participação ampla dos membros e aumento posterior na frequência regular. Adaptem a ideia às necessidades locais, sem transformar a frequência em competição.':'Acompanhe a tendência sem transformar a frequência em competição. Fortaleçam o acolhimento, o contato pessoal e a ministração; reconheçam visitantes e membros que estão retornando.';
if(metric.includes('templo'))return down?'Conversem individualmente sobre preparação para as ordenanças e necessidades de apoio. O conselho pode coordenar ajuda prática e oportunidades de história da família, respeitando a dignidade e a privacidade.':'Mantenham o acompanhamento pessoal e ofereçam apoio para que cada membro avance no próprio ritmo em direção às ordenanças do templo.';
if(metric.includes('Batismos')||metric.includes('Missionários'))return down?'Revisem o plano da Ala para compartilhar o evangelho. Coordenem membros, missionários de tempo integral e ministração, priorizando relacionamentos sinceros e convites adequados.':'Continuem criando oportunidades naturais para compartilhar o evangelho e apoiar pessoas que estão aprendendo, sem tratar resultados como metas individuais.';
if(metric.includes('retornando')||metric.includes('participantes'))return down?'Identifiquem necessidades por meio de ministração e conversas privadas. Distribuam designações claras no conselho da Ala e acompanhem se o apoio foi oferecido.':'Mantenham o contato individual, o acolhimento e oportunidades de participação significativas, adequadas às circunstâncias das pessoas.';
return down?'Leiam a tendência junto com o contexto da Ala. Escolham uma ação simples no conselho, designem responsáveis e revisem o resultado no próximo período.':'Preservem o que está funcionando e avaliem no conselho quais necessidades ainda não estão sendo atendidas.';
}
function TrendChart({points}){
if(!points.length)return <div className="chart-empty">Ainda não há dados suficientes para o gráfico.</div>;
const vals=points.map(p=>Number(p.value)||0),max=Math.max(...vals,1),min=Math.min(...vals,0),range=max-min||1,w=640,h=210,left=42,right=18,top=18,bottom=36;
const coords=vals.map((v,i)=>({x:left+(points.length===1?0:i*(w-left-right)/(points.length-1)),y:top+(max-v)*(h-top-bottom)/range,v}));
const line=coords.map(p=>p.x+','+p.y).join(' ');
return <div className="chart-wrap"><svg viewBox={'0 0 '+w+' '+h} role="img" aria-label="Gráfico de evolução dos indicadores"><line x1={left} y1={h-bottom} x2={w-right} y2={h-bottom} stroke="#dce6df"/><line x1={left} y1={top} x2={left} y2={h-bottom} stroke="#dce6df"/>{coords.map((p,i)=><g key={i}><circle cx={p.x} cy={p.y} r="4" fill="#21483e"/><text x={p.x} y={p.y-10} textAnchor="middle" fontSize="11" fill="#21483e">{p.v}</text><text x={p.x} y={h-12} textAnchor="middle" fontSize="10" fill="#718278">{points[i].label}</text></g>)}<polyline points={line} fill="none" stroke="#2c8061" strokeWidth="3" strokeLinecap="round" strokeLinejoin="round"/></svg></div>;
}
